package service

import (
	"fmt"
	"sync"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// Service provides user-related business logic
type Service struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int
}

// NewService creates and initializes a new Service
func NewService() *Service {
	return &Service{
		users:  make(map[string]User),
		nextID: 1,
	}
}

// CreateUser creates a new user
func (s *Service) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = fmt.Sprintf("%d", s.nextID)
	s.nextID++
	s.users[u.ID] = u
	return u, nil
}

// GetUser retrieves a user by ID
func (s *Service) GetUser(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

// ListUsers lists all users
func (s *Service) ListUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"experiment/internal/service"
)

// Handlers struct holds the service dependency
type Handlers struct {
	Service *service.Service
}

// NewHandlers creates and initializes new Handlers
func NewHandlers(s *service.Service) *Handlers {
	return &Handlers{Service: s}
}

// HandleUsers handles requests to /users
func (h *Handlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		list := h.Service.ListUsers()
		json.NewEncoder(w).Encode(list)

	case http.MethodPost:
		var u service.User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		createdUser, err := h.Service.CreateUser(u)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(createdUser)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID handles requests to /users/{id}
func (h *Handlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	switch r.Method {
	case http.MethodGet:
		u, ok := h.Service.GetUser(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	userService := service.NewService()
	userHandlers := api.NewHandlers(userService)

	http.HandleFunc("/users", userHandlers.HandleUsers)
	http.HandleFunc("/users/", userHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"
)

func TestCreateAndGetUser(t *testing.T) {
	s := NewService()
	user := User{Name: "Test User", Email: "test@example.com"}

	createdUser, err := s.CreateUser(user)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	if createdUser.ID == "" {
		t.Errorf("Expected user ID to be generated, got empty")
	}
	if createdUser.Name != user.Name {
		t.Errorf("Expected user name %s, got %s", user.Name, createdUser.Name)
	}

	retrievedUser, ok := s.GetUser(createdUser.ID)
	if !ok {
		t.Errorf("GetUser failed to retrieve user with ID %s", createdUser.ID)
	}
	if retrievedUser.Name != user.Name {
		t.Errorf("Expected retrieved user name %s, got %s", user.Name, retrievedUser.Name)
	}
}

func TestListUsers(t *testing.T) {
	s := NewService()
	user1 := User{Name: "User 1", Email: "user1@example.com"}
	user2 := User{Name: "User 2", Email: "user2@example.com"}

	s.CreateUser(user1)
	s.CreateUser(user2)

	users := s.ListUsers()
	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/service"
)

func TestHandleUsers_Get(t *testing.T) {
	s := service.NewService()
	handlers := NewHandlers(s)

	user1 := service.User{Name: "User 1", Email: "user1@example.com"}
	user2 := service.User{Name: "User 2", Email: "user2@example.com"}
	s.CreateUser(user1)
	s.CreateUser(user2)

	req, err := http.NewRequest("GET", "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(handlers.HandleUsers)
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("Could not decode response: %v", err)
	}

	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}
}

func TestHandleUsers_Post(t *testing.T) {
	s := service.NewService()
	handlers := NewHandlers(s)

	user := service.User{Name: "New User", Email: "new@example.com"}
	body, _ := json.Marshal(user)

	req, err := http.NewRequest("POST", "/users", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(handlers.HandleUsers)
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusCreated)
	}

	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("Could not decode response: %v", err)
	}

	if createdUser.Name != user.Name {
		t.Errorf("Expected created user name %s, got %s", user.Name, createdUser.Name)
	}
	if createdUser.ID == "" {
		t.Errorf("Expected ID to be generated, got empty")
	}
}

func TestHandleUserByID_Get(t *testing.T) {
	s := service.NewService()
	handlers := NewHandlers(s)

	user := service.User{Name: "Find Me", Email: "findme@example.com"}
	createdUser, _ := s.CreateUser(user)

	req, err := http.NewRequest("GET", "/users/"+createdUser.ID, nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(handlers.HandleUserByID)
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var retrievedUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&retrievedUser); err != nil {
		t.Fatalf("Could not decode response: %v", err)
	}

	if retrievedUser.ID != createdUser.ID {
		t.Errorf("Expected retrieved user ID %s, got %s", createdUser.ID, retrievedUser.ID)
	}
}

func TestHandleUserByID_NotFound(t *testing.T) {
	s := service.NewService()
	handlers := NewHandlers(s)

	req, err := http.NewRequest("GET", "/users/nonexistent", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler := http.HandlerFunc(handlers.HandleUserByID)
	handler.ServeHTTP(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusNotFound)
	}
}
